<?php require __DIR__.'/../config/config.php';$u=login_required();check_csrf();$id=(int)($_POST['status_id']??0);$s=$pdo->prepare('SELECT user_id FROM statuses WHERE id=? AND expires_at>NOW()');$s->execute([$id]);$owner=$s->fetchColumn();if(!$owner)json_out(['error'=>'Status expired'],404);$q=$pdo->prepare('INSERT IGNORE INTO status_views(status_id,viewer_id) VALUES(?,?)');$q->execute([$id,$u['id']]);$v=$pdo->prepare('SELECT u.username,u.full_name,sv.viewed_at FROM status_views sv JOIN users u ON u.id=sv.viewer_id WHERE sv.status_id=? AND ?=?');$v->execute([$id,$owner,$u['id']]);json_out(['ok'=>true]);